class Solution {
public:
    vector<int> goodDaysToRobBank(vector<int>& security, int time) {
        int n = security.size();
        vector<int> result;
        if (time == 0) {
            for (int i = 0; i < n; i++) result.push_back(i);
            return result;
        }
        if (n < 2 * time + 1) return result;

        int leftViol = 0, rightViol = 0;

        for (int j = 0; j < time; j++) {
            if (security[j] < security[j + 1]) leftViol++;
        }
        for (int j = time; j < 2 * time; j++) {
            if (security[j] > security[j + 1]) rightViol++;
        }

        if (leftViol == 0 && rightViol == 0) result.push_back(time);

        for (int i = time + 1; i + time < n; i++) {
            if (security[i - time - 1] < security[i - time]) leftViol--;
            if (security[i - 1] < security[i]) leftViol++;

            if (security[i - 1] > security[i]) rightViol--;
            if (security[i + time - 1] > security[i + time]) rightViol++;

            if (leftViol == 0 && rightViol == 0) result.push_back(i);
        }

        return result;
    }
};
